<template><section class="lottery-system-page"><LotteryConfirmDialog ref="confirmBox" /><LotteryPageHeader title="后台用户管理" subtitle="只展示真实管理员账号，不展示商户核销账号。"><template #actions><button class="orange-button" type="button" data-action="add-user" @click="openCreate">新增后台用户</button></template></LotteryPageHeader><form class="toolbar" data-action="search-users" @submit.prevent="loadUsers"><el-input v-model="filters.userName" data-field="search-user" aria-label="搜索账号" /><el-input v-model="filters.phonenumber" data-field="search-phone" aria-label="搜索手机号" /><button class="soft-button" type="submit">查询</button></form><p v-if="loadError" class="load-error">{{ loadError }} <button type="button" @click="loadUsers">重试</button></p><div class="data-table"><table><thead><tr><th>账号</th><th>昵称</th><th>手机号</th><th>角色</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.userId"><td>{{ user.userName }}</td><td>{{ user.nickName || '—' }}</td><td>{{ user.phonenumber || '—' }}</td><td>{{ roleNames(user) }}</td><td><span class="status" :class="user.status === '0' ? 'on' : 'off'">{{ user.status === '0' ? '已启用' : '已停用' }}</span></td><td>{{ user.createTime || '—' }}</td><td class="row-actions"><button type="button" :data-action="`edit-${user.userId}`" @click="openEdit(user)">编辑</button><button type="button" :data-action="`toggle-${user.userId}`" @click="toggleStatus(user)">{{ user.status === '0' ? '停用' : '启用' }}</button><button type="button" :data-action="`reset-${user.userId}`" @click="openReset(user)">重置密码</button><button class="danger-link" type="button" :data-action="`delete-${user.userId}`" @click="removeUser(user)">删除</button></td></tr></tbody></table><p v-if="!loading && !users.length" class="empty">没有符合条件的后台用户</p></div><div v-if="userDialogVisible" class="dialog-mask" @click.self="closeUserDialog"><form class="dialog-card" data-action="user-form" @submit.prevent="saveUser"><header><div><p class="eyebrow">{{ editing ? '编辑账号' : '新增账号' }}</p><h2>{{ editing ? '维护后台用户' : '创建后台用户' }}</h2></div><button class="close" type="button" @click="closeUserDialog">×</button></header><p v-if="dialogLoading" class="dialog-hint">正在读取真实角色…</p><label>登录账号<el-input v-model="draft.userName" data-field="user-name" :disabled="editing || dialogLoading" required /></label><label>昵称<el-input v-model="draft.nickName" data-field="nick-name" :disabled="dialogLoading" required /></label><label>手机号<el-input v-model="draft.phonenumber" data-field="phone" :disabled="dialogLoading" /></label><label v-if="!editing">初始密码<el-input v-model="draft.password" data-field="password" :disabled="dialogLoading" type="password" required /></label><label>后台角色<el-select v-model="draft.roleIds" data-field="role-selector" :disabled="dialogLoading" multiple><el-option v-for="role in roleOptions" :key="role.roleId" :label="`${role.roleName}（${role.roleKey}）`" :value="role.roleId" /></el-select></label><p class="dialog-hint">必须包含真实 <code>admin</code> 角色；密码修改只可通过“重置密码”。</p><p v-if="formError" class="form-error">{{ formError }}</p><footer><button class="soft-button" type="button" @click="closeUserDialog">取消</button><button class="orange-button" type="submit" :disabled="saving || dialogLoading">保存用户</button></footer></form></div><div v-if="resetDialogVisible" class="dialog-mask" @click.self="resetDialogVisible = false"><form class="dialog-card compact" data-action="reset-form" @submit.prevent="submitReset"><header><h2>重置 {{ resetTarget?.userName }} 的密码</h2><button class="close" type="button" @click="resetDialogVisible = false">×</button></header><label>新密码<el-input v-model="resetPassword" data-field="reset-password" type="password" required /></label><footer><button class="soft-button" type="button" @click="resetDialogVisible = false">取消</button><button class="orange-button" type="submit">确认重置</button></footer></form></div></section></template>
<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import LotteryPageHeader from '@/components/lottery/LotteryPageHeader.vue'
import LotteryConfirmDialog from '@/components/lottery/LotteryConfirmDialog.vue'
import { addUser, changeUserStatus, delUser, getUser, listUser, resetUserPwd, updateUser } from '@/api/system/user'
import { listRole } from '@/api/system/role'
const users=ref([]),loading=ref(false),loadError=ref(''),saving=ref(false),dialogLoading=ref(false),formError=ref(''),filters=ref({userName:'',phonenumber:''}),confirmBox=ref(),userDialogVisible=ref(false),resetDialogVisible=ref(false),resetTarget=ref(),resetPassword=ref(''),editing=ref(false),roleOptions=ref([]),draft=ref(emptyDraft())
function emptyDraft(){return {userId:undefined,userName:'',nickName:'',phonenumber:'',password:'',roleIds:[],postIds:[],status:'0'}}
function rows(response){return response?.rows??response?.data?.rows??[]}
function roleNames(user){return (user.roles??[]).map(role=>role.roleName).filter(Boolean).join('、')||'未分配角色'}
function query(){const result={pageNum:1,pageSize:100};if(filters.value.userName.trim())result.userName=filters.value.userName.trim();if(filters.value.phonenumber.trim())result.phonenumber=filters.value.phonenumber.trim();return result}
async function loadUsers(){loading.value=true;loadError.value='';try{const listed=rows(await listUser(query()));const enriched=await Promise.all(listed.map(async user=>{if(user.roles?.length)return user;try{return {...user,roles:((await getUser(user.userId))?.data?.roles??[])}}catch{return {...user,roles:[]}}}));users.value=enriched.filter(user=>(user.roles||[]).some(role=>role.roleKey==='admin'))}catch(error){loadError.value=error?.message||'后台用户加载失败';ElMessage.error(loadError.value)}finally{loading.value=false}}
function closeUserDialog(){userDialogVisible.value=false}
async function openUserDialog(userId){dialogLoading.value=true;formError.value='';try{const [response,roleResponse]=await Promise.all([getUser(userId),listRole({pageNum:1,pageSize:100,roleKey:'admin'})]);const detail=response?.data??{};roleOptions.value=rows(roleResponse).filter(role=>role.roleKey==='admin');const admin=roleOptions.value[0];if(!admin)throw new Error('当前权限下没有可分配的管理员角色');draft.value={...emptyDraft(),...detail,userId:userId??detail.userId,password:'',roleIds:response?.roleIds??detail.roleIds??[],postIds:response?.postIds??detail.postIds??[]};if(!userId)draft.value.roleIds=[admin.roleId];userDialogVisible.value=true}catch(error){formError.value=error?.message||'角色与账号详情加载失败';ElMessage.error(formError.value)}finally{dialogLoading.value=false}}
function openCreate(){editing.value=false;return openUserDialog()};function openEdit(user){editing.value=true;return openUserDialog(user.userId)}
function hasAdminRole(){return draft.value.roleIds.some(id=>roleOptions.value.some(role=>role.roleId===id&&role.roleKey==='admin'))}
function userPayload(){const payload={...draft.value,userName:draft.value.userName.trim(),nickName:draft.value.nickName.trim(),phonenumber:draft.value.phonenumber.trim(),roleIds:[...draft.value.roleIds],postIds:[...draft.value.postIds],status:String(draft.value.status??'0')};delete payload.roles;if(editing.value)delete payload.password;return payload}
async function saveUser(){formError.value='';if(!hasAdminRole()){formError.value='请选择管理员角色后再保存';return}if(!editing.value&&!draft.value.password){formError.value='请设置初始密码';return}saving.value=true;try{const payload=userPayload();if(editing.value)await updateUser(payload);else{delete payload.userId;await addUser(payload)}closeUserDialog();await loadUsers()}catch(error){formError.value=error?.message||'保存后台用户失败';ElMessage.error(formError.value)}finally{saving.value=false}}
async function toggleStatus(user){const next=user.status==='0'?'1':'0';if(next==='1'&&!await confirmBox.value.open({title:'停用后台用户',message:`停用“${user.userName}”后将不能登录管理端。`,confirmText:'确认停用',danger:true}))return;try{await changeUserStatus(user.userId,next);await loadUsers()}catch(error){ElMessage.error(error?.message||'状态更新失败')}}
function openReset(user){resetTarget.value=user;resetPassword.value='';resetDialogVisible.value=true};async function submitReset(){if(!resetTarget.value||!resetPassword.value)return;try{await resetUserPwd(resetTarget.value.userId,resetPassword.value);resetDialogVisible.value=false;await loadUsers()}catch(error){ElMessage.error(error?.message||'密码重置失败')}}
async function removeUser(user){if(!await confirmBox.value.open({title:'删除后台用户',message:`确定删除“${user.userName}”吗？`,confirmText:'确认删除',danger:true}))return;try{await delUser(user.userId);await loadUsers()}catch(error){ElMessage.error(error?.message||'删除后台用户失败')}}
onMounted(loadUsers)
</script>
<style scoped>
.lottery-system-page{display:grid;gap:20px;max-width:1280px;margin:auto;padding:var(--lottery-space-4) var(--lottery-space-5) 60px}.toolbar,.row-actions{display:flex;flex-wrap:wrap;gap:10px}.toolbar :deep(.el-input){width:min(280px,100%)}.toolbar :deep(.el-input__wrapper),.toolbar :deep(.el-select__wrapper),.dialog-card :deep(.el-input__wrapper),.dialog-card :deep(.el-select__wrapper){min-height:44px}.dialog-card :deep(.el-input),.dialog-card :deep(.el-select){min-height:44px}button{min-height:44px;border-radius:12px;padding:0 16px;font-weight:700;cursor:pointer}.orange-button{border:0;background:var(--lottery-orange);color:#fff}.soft-button{border:1px solid var(--lottery-border);background:var(--lottery-paper);color:var(--lottery-ink)}.data-table{overflow:auto;border:1px solid var(--lottery-border);border-radius:var(--lottery-radius-lg);background:var(--lottery-paper);box-shadow:var(--lottery-shadow)}table{width:100%;min-width:960px;border-collapse:collapse;text-align:left}th,td{padding:15px 16px;border-bottom:1px solid var(--lottery-border)}th{background:#faf8f5;color:var(--lottery-muted);font-size:13px}.row-actions button{border:0;background:transparent;color:var(--lottery-orange)}.row-actions .danger-link{color:#c64735}.status{display:inline-flex;min-height:26px;align-items:center;padding:0 9px;border-radius:99px;font-size:12px}.on{background:#edf8ef;color:#267345}.off{background:#fff0ec;color:#bd4938}.empty{padding:32px;text-align:center;color:var(--lottery-muted)}.load-error,.form-error{padding:12px;border-radius:12px;background:#fff0ec;color:#a94235}.dialog-mask{position:fixed;z-index:10010;inset:0;display:grid;place-items:center;padding:16px;background:rgb(45 33 27 / 42%)}.dialog-card{width:min(100%,560px);max-height:min(760px,calc(100vh - 32px));overflow:auto;display:grid;gap:15px;padding:24px;border:1px solid var(--lottery-border);border-radius:var(--lottery-radius-xl);background:var(--lottery-paper);box-shadow:var(--lottery-shadow)}.compact{width:min(100%,460px)}.dialog-card header{display:flex;justify-content:space-between;gap:12px}.dialog-card h2,.dialog-card p{margin:0}.eyebrow{color:var(--lottery-orange);font-size:13px;font-weight:800}.close{border:0;background:transparent;color:var(--lottery-muted);font-size:28px}.dialog-card label{display:grid;gap:7px;color:var(--lottery-ink);font-size:14px;font-weight:700}.dialog-hint{color:var(--lottery-muted);font-size:13px;line-height:1.6}.dialog-card footer{display:flex;justify-content:flex-end;gap:10px}@media(max-width:600px){.lottery-system-page{padding:20px 16px 44px}.toolbar>*{width:100%}.toolbar :deep(.el-input){width:100%}.dialog-card{padding:20px}.dialog-card footer>*{flex:1}.row-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.row-actions button{width:100%}}
</style>
